"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[980],{5888(e,t,n){n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>l,default:()=>p,frontMatter:()=>c,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"part2-backend-platform-security/concurrency-user-isolation","title":"FastAPI Concurrency and Per-Request User Isolation","description":"How one service keeps many in-flight requests efficient without mixing user or tenant state.","source":"@site/docs/part2-backend-platform-security/04-concurrency-user-isolation.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/04-concurrency-user-isolation","permalink":"/tutorials/part2-backend-platform-security/04-concurrency-user-isolation","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":4,"frontMatter":{"title":"FastAPI Concurrency and Per-Request User Isolation","slug":"/part2-backend-platform-security/04-concurrency-user-isolation","description":"How one service keeps many in-flight requests efficient without mixing user or tenant state.","sidebar_label":"5. Concurrency and user isolation","pagination_label":"5. Concurrency and user isolation","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"4. Pydantic data models","permalink":"/tutorials/part2-backend-platform-security/04-pydantic-data-models"},"next":{"title":"6. Background tasks and retries","permalink":"/tutorials/part2-backend-platform-security/05-background-tasks-and-retries"}}');var a=n(4848),i=n(8453),s=n(8172);const o=JSON.parse('{"sourcePath":"part2-backend-platform-security/04-concurrency-user-isolation.html","route":"/part2-backend-platform-security/04-concurrency-user-isolation","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"FastAPI Concurrency and Per-Request User Isolation","title":"FastAPI Concurrency and Per-Request User Isolation","description":"How one service keeps many in-flight requests efficient without mixing user or tenant state.","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-what-happens-when-1000-users-hit-your-api","label":"1. What happens when 1000 users hit your API"},{"id":"2-why-async-lets-one-server-handle-lots-of-traffic","label":"2. Why async lets one server handle lots of traffic"},{"id":"3-concurrency-vs-parallelism","label":"3. Concurrency vs. Parallelism"},{"id":"4-how-fastapi-keeps-users-separate-per-request-identity","label":"4. How FastAPI keeps users separate (Per-Request Identity)"},{"id":"5-critical-rule-no-global-state","label":"5. Critical Rule: No Global State"},{"id":"6-tenant-isolation-must-survive-every-boundary","label":"6. Tenant isolation must survive every boundary"},{"id":"7-backpressure-is-part-of-concurrency-design","label":"7. Backpressure is part of concurrency design"},{"id":"8-cancellation-disconnects-and-observability","label":"8. Cancellation, disconnects, and observability"}],"html":"<div class=\\"container\\">\\n        \\n        <p class=\\"lead\\">How one service keeps many in-flight requests efficient without mixing user or tenant state.</p>\\n\\n        <div class=\\"tr-note\\">\\n            <strong>Where this fits</strong>\\n            The preceding chapter established typed request boundaries with\\n            Pydantic. This chapter follows several validated requests while\\n            they execute at the same time. The next chapter moves slow work\\n            into durable background jobs without losing the same identity and\\n            tenant context.\\n        </div>\\n\\n        <figure class=\\"figure-card\\">\\n            <svg viewBox=\\"0 0 980 360\\" role=\\"img\\" aria-labelledby=\\"concurrency-title concurrency-desc\\">\\n                <title id=\\"concurrency-title\\">Concurrent requests sharing an event loop while retaining separate state</title>\\n                <desc id=\\"concurrency-desc\\">Alice and Bob have independent request contexts. When one request awaits I/O, the event loop advances the other. Both calls reach tenant-scoped repositories.</desc>\\n                <defs>\\n                    <marker id=\\"concurrency-arrow-blue\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n                        <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#1769e0\\"></path>\\n                    </marker>\\n                    <marker id=\\"concurrency-arrow-green\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n                        <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#14875a\\"></path>\\n                    </marker>\\n                </defs>\\n                <rect x=\\"30\\" y=\\"35\\" width=\\"170\\" height=\\"100\\" rx=\\"12\\" fill=\\"#e8f2ff\\" stroke=\\"#1769e0\\" stroke-width=\\"2\\"></rect>\\n                <text x=\\"115\\" y=\\"72\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Alice request</text>\\n                <text x=\\"115\\" y=\\"101\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">tenant-acme</text>\\n\\n                <rect x=\\"30\\" y=\\"225\\" width=\\"170\\" height=\\"100\\" rx=\\"12\\" fill=\\"#e9fbf2\\" stroke=\\"#14875a\\" stroke-width=\\"2\\"></rect>\\n                <text x=\\"115\\" y=\\"262\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Bob request</text>\\n                <text x=\\"115\\" y=\\"291\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">tenant-north</text>\\n\\n                <rect x=\\"305\\" y=\\"105\\" width=\\"235\\" height=\\"150\\" rx=\\"14\\" fill=\\"#f1ecff\\" stroke=\\"#7548d8\\" stroke-width=\\"2\\"></rect>\\n                <text x=\\"422\\" y=\\"145\\" text-anchor=\\"middle\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">Uvicorn event loop</text>\\n                <text x=\\"422\\" y=\\"178\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">run A until await</text>\\n                <text x=\\"422\\" y=\\"205\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">run B while A waits</text>\\n                <text x=\\"422\\" y=\\"232\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">resume A when ready</text>\\n\\n                <rect x=\\"665\\" y=\\"35\\" width=\\"280\\" height=\\"100\\" rx=\\"12\\" fill=\\"#e8f2ff\\" stroke=\\"#1769e0\\" stroke-width=\\"2\\"></rect>\\n                <text x=\\"805\\" y=\\"72\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Scoped repository call</text>\\n                <text x=\\"805\\" y=\\"101\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">WHERE tenant_id = tenant-acme</text>\\n\\n                <rect x=\\"665\\" y=\\"225\\" width=\\"280\\" height=\\"100\\" rx=\\"12\\" fill=\\"#e9fbf2\\" stroke=\\"#14875a\\" stroke-width=\\"2\\"></rect>\\n                <text x=\\"805\\" y=\\"262\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Scoped repository call</text>\\n                <text x=\\"805\\" y=\\"291\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">WHERE tenant_id = tenant-north</text>\\n\\n                <path d=\\"M200 85 C250 85 260 135 305 150\\" fill=\\"none\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#concurrency-arrow-blue)\\"></path>\\n                <path d=\\"M200 275 C250 275 260 225 305 210\\" fill=\\"none\\" stroke=\\"#14875a\\" stroke-width=\\"3\\" marker-end=\\"url(#concurrency-arrow-green)\\"></path>\\n                <path d=\\"M540 150 C590 135 610 85 665 85\\" fill=\\"none\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#concurrency-arrow-blue)\\"></path>\\n                <path d=\\"M540 210 C590 225 610 275 665 275\\" fill=\\"none\\" stroke=\\"#14875a\\" stroke-width=\\"3\\" marker-end=\\"url(#concurrency-arrow-green)\\"></path>\\n            </svg>\\n            <figcaption>\\n                Concurrency interleaves execution; it does not merge local\\n                variables. Isolation fails only when application code stores\\n                request-specific data in shared state or omits tenant filters.\\n            </figcaption>\\n        </figure>\\n\\n        <h2 id=\\"1-what-happens-when-1000-users-hit-your-api\\">1. What happens when 1000 users hit your API</h2>\\n        <p>When thousands of users call your FastAPI endpoint simultaneously, Uvicorn (the ASGI server) accepts the connections. Within each worker process, the ASGI application handles each active request in its own in-flight task and request scope.</p>\\n        <p>For every single request, FastAPI:</p>\\n        <ul>\\n            <li>Matches the method + path (e.g., <code>POST /query</code>) to the correct function.</li>\\n            <li>Parses headers, query parameters, and the body specific to that request.</li>\\n            <li>Calls your function with fresh arguments.</li>\\n        </ul>\\n        <div class=\\"highlight-box\\">\\n            <strong>Key Concept:</strong> Each user request triggers an independent function call.\\n        </div>\\n        <p>\\n            Function arguments and local variables belong to that invocation.\\n            They are safe to interleave because Request A does not reuse\\n            Request B\'s Python stack frame. This is request isolation, not\\n            authorization: your code must still verify the caller and scope\\n            every data operation.\\n        </p>\\n\\n        <h2 id=\\"2-why-async-lets-one-server-handle-lots-of-traffic\\">2. Why async lets one server handle lots of traffic</h2>\\n        <p>Most API operations are <strong>I/O-bound</strong>: waiting for database queries, Elasticsearch results, or external APIs (like Azure OpenAI).</p>\\n        <p>If your endpoint is defined with <code>async def</code> and uses <code>await</code> for I/O, the event loop can pause a waiting request (Request A) and process others (Request B, C) in the meantime. This allows a single process to handle thousands of concurrent connections efficiently.</p>\\n\\n<pre><code class=\\"language-python\\">@app.post(\\"/query\\")\\nasync def query():\\n    chunks = await es_search(...)       # waiting -&gt; event loop runs other requests\\n    answer = await call_openai(...)     # waiting -&gt; event loop runs other requests\\n    return {\\"answer\\": answer}</code></pre>\\n\\n        <div class=\\"warning-box\\">\\n            <strong>Important:</strong> If you use blocking code (like <code>time.sleep()</code> or a synchronous HTTP client) inside <code>async def</code>, you freeze the event loop and kill concurrency.\\n        </div>\\n        <p>\\n            <code>async def</code> helps only when the libraries underneath it\\n            are asynchronous and the function reaches an <code>await</code>.\\n            A synchronous FastAPI endpoint is normally run in a thread pool,\\n            which is useful for blocking libraries but has finite capacity.\\n            CPU-heavy inference, image processing, and large dataframe work\\n            should use a separate process, worker service, or batch platform\\n            rather than occupying the API event loop.\\n        </p>\\n\\n        <h2 id=\\"3-concurrency-vs-parallelism\\">3. Concurrency vs. Parallelism</h2>\\n        <p>It is important to distinguish between these two scaling mechanisms:</p>\\n        <div class=\\"comparison-grid\\">\\n            <div class=\\"concept-box\\">\\n                <h3 id=\\"a-async-concurrency\\">A) Async Concurrency</h3>\\n                <p><em>(Recommended for I/O)</em></p>\\n                <ul>\\n                    <li>One process + one event loop.</li>\\n                    <li>Thousands of \u201ctasks\u201d can be in flight.</li>\\n                    <li>Best when you <code>await</code> I/O operations.</li>\\n                </ul>\\n            </div>\\n            <div class=\\"concept-box\\">\\n                <h3 id=\\"b-parallelism-workers\\">B) Parallelism (Workers)</h3>\\n                <p><em>(Multi-process)</em></p>\\n                <ul>\\n                    <li>Run multiple Uvicorn worker processes.</li>\\n                    <li>Each process has its own event loop.</li>\\n                    <li>Utilizes multiple CPU cores.</li>\\n                </ul>\\n            </div>\\n        </div>\\n        <p>\\n            Production systems usually combine both mechanisms: asynchronous\\n            I/O inside each worker, several workers or container replicas for\\n            CPU capacity and resilience, and a load balancer in front. Worker\\n            count is not a substitute for sizing database and HTTP connection\\n            pools; every replica can multiply downstream connections.\\n        </p>\\n\\n        <h2 id=\\"4-how-fastapi-keeps-users-separate-per-request-identity\\">4. How FastAPI keeps users separate (Per-Request Identity)</h2>\\n        <p>FastAPI does not \u201cassign a user to a thread.\u201d Instead, every HTTP request is isolated. User identity is derived from the request itself (usually via a JWT in the <code>Authorization</code> header), and your code uses this identity to scope data access.</p>\\n\\n        <h3 id=\\"concrete-example\\">Concrete Example</h3>\\n        <p>Two users hit the same endpoint at the same time, but get different results.</p>\\n\\n<pre><code class=\\"language-python\\">from typing import Annotated\\n\\nfrom fastapi import Depends, FastAPI, Header, HTTPException, status\\nfrom pydantic import BaseModel\\n\\napp = FastAPI()\\n\\nclass QueryReq(BaseModel):\\n    question: str\\n\\nclass Identity(BaseModel):\\n    tenant_id: str\\n    user_id: str\\n\\n# Dependency to extract identity from a verified bearer token\\ndef get_identity(\\n    authorization: Annotated[str | None, Header()] = None,\\n) -&gt; Identity:\\n    if not authorization or not authorization.startswith(\\"Bearer \\"):\\n        raise HTTPException(\\n            status_code=status.HTTP_401_UNAUTHORIZED,\\n            detail=\\"Missing bearer token\\",\\n        )\\n\\n    token = authorization.removeprefix(\\"Bearer \\").strip()\\n\\n    # Verify signature, issuer, audience, expiry, and required claims.\\n    claims = verify_and_decode_jwt(token)\\n    return Identity(tenant_id=claims[\\"tenant_id\\"], user_id=claims[\\"sub\\"])\\n\\n@app.post(\\"/query\\")\\nasync def query(\\n    req: QueryReq,\\n    ident: Annotated[Identity, Depends(get_identity)],\\n):\\n    # The repository requires tenant_id; callers cannot \\"forget\\" the filter.\\n    chunks = await search_repository.search(\\n        tenant_id=ident.tenant_id,\\n        question=req.question,\\n    )\\n    return {\\"user_id\\": ident.user_id, \\"chunks\\": chunks}</code></pre>\\n\\n        <div class=\\"comparison-grid\\">\\n            <div class=\\"concept-box\\">\\n                <h4>User A Request</h4>\\n                <pre>Authorization: Bearer &lt;verified JWT for Alice&gt;</pre>\\n                <p>FastAPI calls:</p>\\n                <code>ident=Identity(tenant_id=\\"tenant-1\\", ...)</code>\\n            </div>\\n            <div class=\\"concept-box\\">\\n                <h4>User B Request</h4>\\n                <pre>Authorization: Bearer &lt;verified JWT for Bob&gt;</pre>\\n                <p>FastAPI calls:</p>\\n                <code>ident=Identity(tenant_id=\\"tenant-2\\", ...)</code>\\n            </div>\\n        </div>\\n        <p>Same code, same route \u2014 but different identity \u2192 tenants stay isolated.</p>\\n\\n        <h2 id=\\"5-critical-rule-no-global-state\\">5. Critical Rule: No Global State</h2>\\n        <div class=\\"warning-box\\">\\n            <strong>Never use global variables for per-user state.</strong> Globals are shared across all requests in a process.\\n            <br><br>\\n            <br><br>\\n            <code>CURRENT_USER = None  # unsafe: shared across requests in this process</code>\\n        </div>\\n        <p>Instead, keep per-user/per-request data in:</p>\\n        <ul>\\n            <li>Function local variables (<code>ident</code>, <code>req</code>)</li>\\n            <li>Dependencies (<code>Depends(get_identity)</code>)</li>\\n            <li><code>request.state</code> (middleware context)</li>\\n        </ul>\\n\\n        <p>\\n            Module-level objects are not automatically wrong. Immutable\\n            configuration, database pool objects, HTTP clients, and model\\n            clients are normally shared. The unsafe pattern is putting\\n            mutable request data such as <code>current_user</code>,\\n            <code>tenant_id</code>, or a partially built response in them.\\n        </p>\\n\\n        <h2 id=\\"6-tenant-isolation-must-survive-every-boundary\\">6. Tenant isolation must survive every boundary</h2>\\n        <p>\\n            A verified identity is only the starting point. Carry the derived\\n            tenant and user identifiers through every call that can read,\\n            cache, enqueue, or store data.\\n        </p>\\n        <table>\\n            <thead>\\n                <tr><th>Boundary</th><th>Isolation rule</th><th>Typical backstop</th></tr>\\n            </thead>\\n            <tbody>\\n                <tr><td>Repository / SQL</td><td>Require <code>tenant_id</code> in the method signature and query predicate.</td><td>Row-level security and composite constraints.</td></tr>\\n                <tr><td>Search index</td><td>Add a non-optional tenant filter to every query.</td><td>Separate index/namespace for higher-risk tenants.</td></tr>\\n                <tr><td>Cache</td><td>Include tenant and authorization-relevant version data in the key.</td><td>Short TTL and explicit invalidation.</td></tr>\\n                <tr><td>Object storage</td><td>Derive the allowed prefix from trusted request context, never from an unchecked body field.</td><td>Separate buckets or policy conditions where appropriate.</td></tr>\\n                <tr><td>Background job</td><td>Persist tenant, initiating user, authorization snapshot/version, and job ID.</td><td>Worker-side re-authorization for sensitive effects.</td></tr>\\n            </tbody>\\n        </table>\\n\\n        <h2 id=\\"7-backpressure-is-part-of-concurrency-design\\">7. Backpressure is part of concurrency design</h2>\\n        <p>\\n            Accepting more concurrent requests than downstream systems can\\n            serve creates a queue inside your application. Latency rises,\\n            retries multiply the load, and eventually everything times out.\\n            Bound concurrency deliberately:\\n        </p>\\n        <ul>\\n            <li>Set connection-pool limits for databases and outbound HTTP clients.</li>\\n            <li>Use explicit connect, read, write, and pool-acquisition timeouts.</li>\\n            <li>Use a semaphore or worker queue around scarce downstream capacity.</li>\\n            <li>Return <code>429 Too Many Requests</code> for caller-specific rate limits and <code>503 Service Unavailable</code> when shared capacity is temporarily exhausted.</li>\\n            <li>Retry only transient failures, with exponential backoff and jitter; Chapter 6 develops that policy.</li>\\n        </ul>\\n\\n        <h2 id=\\"8-cancellation-disconnects-and-observability\\">8. Cancellation, disconnects, and observability</h2>\\n        <p>\\n            A client can disconnect while work is still running. Cooperative\\n            asynchronous libraries can receive cancellation, but an external\\n            side effect may already have happened. Use idempotency keys for\\n            effects, keep request deadlines shorter than infrastructure\\n            deadlines, and move work that must finish after disconnect into a\\n            durable job.\\n        </p>\\n        <p>\\n            Logs and traces should include a request ID, tenant ID, subject or\\n            internal user ID, route, downstream dependency, and latency. Do\\n            not log bearer tokens, raw secrets, or unnecessary personal data.\\n            A load test is incomplete unless it also checks cross-tenant\\n            leakage and downstream pool saturation.\\n        </p>\\n\\n        <div class=\\"tr-tip\\">\\n            <strong>Operational test</strong>\\n            Run Alice and Bob requests concurrently, deliberately delay one\\n            downstream call, and assert that each response, cache key, SQL\\n            query, trace, and queued message retains the correct tenant.\\n        </div>\\n    </div>"}'),c={title:"FastAPI Concurrency and Per-Request User Isolation",slug:"/part2-backend-platform-security/04-concurrency-user-isolation",description:"How one service keeps many in-flight requests efficient without mixing user or tenant state.",sidebar_label:"5. Concurrency and user isolation",pagination_label:"5. Concurrency and user isolation",hide_title:!0,hide_table_of_contents:!0},l=void 0,d={},u=[];function h(e){return(0,a.jsx)(s.A,{content:o})}function p(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h()}}}]);